describe("doctests of sympy.matrices.expressions.matexpr", () => {
  it("I.as_explicit()", () => {
    expect(sympyStr(Identity(rational(3)).asExplicit())).toBe('Matrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]])');
  });
  it("I.shape", () => {
    const v1 = rational(3);
    expect(sympyMatches([v1, v1], '(3, 3)')).toBe(true);
  });
  it("I.as_mutable()", () => {
    expect(sympyStr(Identity(rational(3)).asMutable())).toBe('Matrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]])');
  });
  it("Identity(3).equals(eye(3))", () => {
    expect(sympyStr(Identity(rational(3)).equalsExplicit(ImmutableDenseMatrix(Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]))))).toBe('True');
  });
  it("MatrixExpr.from_index_summation(expr)", () => {
    const [N, i, j, k] = symbols('N i j k');
    expect(sympyStr(fromIndexSummation(Sum(mul(MatrixElement(new MatrixSymbol('A', N, N), i, j), MatrixElement(new MatrixSymbol('B', N, N), j, k)), [j, rational(0), add(-1, N)])))).toBe('A*B');
  });
  it("MatrixExpr.from_index_summation(expr) (2)", () => {
    const [N, j, i, k] = symbols('N j i k');
    expect(sympyStr(fromIndexSummation(Sum(mul(MatrixElement(new MatrixSymbol('A', N, N), j, i), MatrixElement(new MatrixSymbol('B', N, N), j, k)), [j, rational(0), add(-1, N)])))).toBe('A.T*B');
  });
  it("MatrixExpr.from_index_summation(expr) (3)", () => {
    const [N, i] = symbols('N i');
    expect(sympyStr(fromIndexSummation(Sum(MatrixElement(new MatrixSymbol('A', N, N), i, i), [i, rational(0), add(-1, N)])))).toBe('Trace(A)');
  });
  it("MatrixExpr.from_index_summation(expr) (4)", () => {
    const [N, i, j, l, k] = symbols('N i j l k');
    expect(sympyStr(fromIndexSummation(Sum(mul(MatrixElement(new MatrixSymbol('A', N, N), i, j), MatrixElement(new MatrixSymbol('A', N, N), l, k), MatrixElement(new MatrixSymbol('B', N, N), k, j)), [j, rational(0), add(-1, N)], [k, rational(0), add(-1, N)])))).toBe('A*B.T*A.T');
  });
  it("A.shape", () => {
    expect(sympyMatches([rational(3), rational(4)], '(3, 4)')).toBe(true);
  });
  it("2*A*B + Identity(3)", () => {
    expect(sympyStr(MatMul(rational(2), new MatrixSymbol('A', rational(3), rational(4)), new MatrixSymbol('B', rational(4), rational(3))).add(Identity(rational(3))))).toBe('I + 2*A*B');
  });
  it("I", () => {
    expect(sympyStr(Identity(rational(3)))).toBe('I');
  });
  it("I (2)", () => {
    expect(sympyStr(Identity(rational(3)))).toBe('I');
  });
});

