describe("sympy/matrices/expressions/tests/test_determinant.py", () => {
  it("test_det:22", () => {
    expect(() => Determinant(new MatrixSymbol('C', rational(3), rational(4)))).toThrow(ShapeError);
  });
  it("test_det:23", () => {
    expect(sympyStr(Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]).det())).toBe('1');
  });
  it("test_det:24", () => {
    expect(sympyStr(Matrix.of([[rational(1), rational(3), rational(2)], [rational(4), rational(1), rational(3)], [rational(2), rational(5), rational(2)]]).det())).toBe('17');
  });
  it("test_det:27", () => {
    expect(() => Determinant(rational(1))).toThrow(TypeError);
  });
  it("test_eval_determinant:33", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(det(Identity(n)))).toBe('1');
  });
  it("test_eval_determinant:34", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(det(ZeroMatrix(n, n)))).toBe('0');
  });
  it("test_eval_determinant:35", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(det(OneMatrix(n, n)))).toBe('Determinant(1)');
  });
  it("test_eval_determinant:36", () => {
    expect(sympyStr(det(OneMatrix(rational(1), rational(1))))).toBe('1');
  });
  it("test_eval_determinant:37", () => {
    expect(sympyStr(det(OneMatrix(rational(2), rational(2))))).toBe('0');
  });
  it("test_eval_determinant:38", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(det(Transpose(new MatrixSymbol('A', n, n))))).toBe('Determinant(A)');
  });
  it("test_eval_determinant:39", () => {
    expect(sympyStr(Determinant(MatMul(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]]), Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]]))).doit({ deep: true }))).toBe('1');
  });
  it.fails("test_refine:43", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(refine(Determinant(new MatrixSymbol('A', n, n)), Q.orthogonal(new MatrixSymbol('A', n, n))))).toBe('1');
  });
  it.fails("test_refine:44", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(refine(Determinant(new MatrixSymbol('A', n, n)), Q.singular(new MatrixSymbol('A', n, n))))).toBe('0');
  });
  it.fails("test_refine:45", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(refine(Determinant(new MatrixSymbol('A', n, n)), Q.unit_triangular(new MatrixSymbol('A', n, n))))).toBe('1');
  });
  it("test_refine:46", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(refine(Determinant(new MatrixSymbol('A', n, n)), Q.normal(new MatrixSymbol('A', n, n))))).toBe('Determinant(A)');
  });
  it("test_commutative:52", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(Determinant(new MatrixSymbol('A', n, n)).isCommutative)).toBe('True');
  });
  it("test_commutative:53", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(Determinant(new MatrixSymbol('B', n, n)).isCommutative)).toBe('True');
  });
  it("test_commutative:54", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(Determinant(new MatrixSymbol('A', n, n)).mul(Determinant(new MatrixSymbol('B', n, n))))).toBe('Determinant(A)*Determinant(B)');
  });
  it("test_permanent:61", () => {
    expect(sympyStr(Permanent(Matrix.of([[rational(1), rational(1), rational(1)], [rational(1), rational(1), rational(1)], [rational(1), rational(1), rational(1)]])).doit())).toBe('6');
  });
  it("test_permanent:63", () => {
    expect(sympyStr(per(Matrix.of([[rational(1), rational(3), rational(2)], [rational(4), rational(1), rational(3)], [rational(2), rational(5), rational(2)]])))).toBe('103');
  });
  it("test_permanent:64", () => {
    expect(() => Permanent(rational(1))).toThrow(TypeError);
  });
});

